/**
 * @file src/lib/questRewardTooltips.ts
 * Shared tooltip labels and delegation for quest reward chips.
 */

import type { GameRuntime } from '../types/game.js';

export type QuestRewardTooltipKind =
  | 'pokedollars'
  | 'questTokens'
  | 'triumphMarks'
  | 'essenceDust'
  | 'combatTickets'
  | 'talentRerolls'
  | 'eggs';

const TOOLTIP_I18N: Record<QuestRewardTooltipKind, { key: string; fallback: string }> = {
  pokedollars: { key: 'stats.moneyLabel', fallback: 'Pokédollars' },
  questTokens: { key: 'quests.tokensLabel', fallback: 'Jetons' },
  triumphMarks: { key: 'tower.marksLabel', fallback: 'Marques du Triomphe' },
  essenceDust: { key: 'shop.essenceDustLabel', fallback: "Poussière d'essence" },
  combatTickets: { key: 'combatTickets', fallback: 'Tickets de combat' },
  talentRerolls: { key: 'bag.talentRerollLabel', fallback: 'Pilule talent' },
  eggs: { key: 'dailyLogin.eggCommon', fallback: 'Œufs' },
};

export function questRewardTooltipTitle(
  game: GameRuntime,
  kind: QuestRewardTooltipKind,
): string {
  const { key, fallback } = TOOLTIP_I18N[kind];
  const raw = typeof game.t === 'function' ? game.t(key) : '';
  const label = raw && raw !== key ? raw : fallback;
  return label.replace(/:\s*$/, '').trim();
}

export function bindQuestRewardTooltipEvents(container: HTMLElement, game: GameRuntime): void {
  if (container.dataset.questRewardTooltipBound === '1') return;
  if (!game || typeof game.scheduleTooltip !== 'function') return;
  container.dataset.questRewardTooltipBound = '1';

  container.addEventListener('mouseover', (ev) => {
    const node = (ev.target as HTMLElement).closest('.quest-reward-item[data-tooltip-title]');
    if (!node) return;
    const title = (node as HTMLElement).dataset.tooltipTitle || '';
    if (!title) return;
    game.scheduleTooltip(ev, title, '', 50);
  });
  container.addEventListener('mouseout', (ev) => {
    const node = (ev.target as HTMLElement).closest('.quest-reward-item[data-tooltip-title]');
    if (node && typeof game.hideTooltip === 'function') {
      game.hideTooltip();
    }
  });
}
